// Regenerate additive homepage assets after changing style.css or either original hero image.
// Requires ImageMagick. Original CSS and images are kept unchanged.
const fs = require('node:fs');
const path = require('node:path');
const {execFileSync} = require('node:child_process');
const root = path.resolve(__dirname, '..');
const assets = path.join(root, 'assets');
const css = fs.readFileSync(path.join(assets, 'style.css'), 'utf8');
fs.writeFileSync(path.join(assets, 'home-base-v2.css'),
  '/* Generated by scripts/build-home-performance.cjs. Homepage header styles are linked in HTML. */\n' +
  css.replace(/font-display:swap/g, 'font-display:optional').replace(/\/\* Header styles[\s\S]*?\*\/\s*/, '').replace(/@import url\("\/assets\/(?:shared-header|lang-switch)\.css\?v=\d+"\);/g, ''));
for (const lang of ['en', 'ur']) {
  const file = path.join(root, lang, 'index.html');
  let html = fs.readFileSync(file, 'utf8');
  html = html.replace('/assets/home-base-v1.css', '/assets/home-base-v2.css');
  html = html.replace(/href="(?:\.\.\/|\/)assets\/style\.css"/, 'href="/assets/home-base-v2.css"');
  html = html.replace(/(<div class="art">)<img ([^>]+)>/, (_, div, attrs) => {
    const src = attrs.match(/src="([^"]+)"/)[1];
    const original = path.basename(src);
    const stem = original.replace(/\.webp$/, '');
    const variants = [640, 1024, 1440].map(width => {
      const name = `${stem}-${width}w.webp`;
      execFileSync('magick', [path.join(assets, original), '-resize', `${width}x`, '-quality', '82', path.join(assets, name)]);
      return `/assets/${name} ${width}w`;
    });
    variants.push(`${src} 2400w`);
    attrs = attrs.replace(/\s(?:srcset|sizes)="[^"]*"/g, '');
    return `${div}<img ${attrs} srcset="${variants.join(', ')}" sizes="(max-width: 980px) 134vw, (max-width: 1939px) 66vw, 1280px">`;
  });
  fs.writeFileSync(file, html);
}
